(function(){'use strict';var SEL='.lazyload[data-bg],video.lazyload,iframe.lazyload';function reveal(el){if(!el || el.dataset.easyoptDone){return;}el.dataset.easyoptDone='1';el.classList.remove('lazyload');el.classList.add('lazyloading');var bg=el.getAttribute('data-bg');if(bg){el.style.backgroundImage='url("'+bg.replace(/"/g,'\\"')+'")';el.removeAttribute('data-bg');}if('IFRAME'===el.tagName){var src=el.getAttribute('data-src');if(src){el.setAttribute('src',src);el.removeAttribute('data-src');}}if('VIDEO'===el.tagName){restoreVideo(el);}el.classList.remove('lazyloading');el.classList.add('lazyloaded');}function restoreVideo(video){var preload=video.getAttribute('data-preload');if(preload){video.setAttribute('preload',preload);video.removeAttribute('data-preload');}if(!video.hasAttribute('data-autoplay')){return;}video.removeAttribute('data-autoplay');video.muted=true;video.setAttribute('muted','');video.setAttribute('playsinline','');video.setAttribute('autoplay','');try{video.load();}catch(e){}var attempt=video.play();if(attempt && 'function'===typeof attempt.catch){attempt.catch(function(){});}}function boot(){var nodes=document.querySelectorAll(SEL);if(!nodes.length){return;}if(!('IntersectionObserver' in window)){Array.prototype.forEach.call(nodes,reveal);return;}var io=new IntersectionObserver(function(entries){for(var i=0;i<entries.length;i++){if(entries[i].isIntersecting){io.unobserve(entries[i].target);reveal(entries[i].target);}}},{rootMargin:'200px 0px',threshold:0});Array.prototype.forEach.call(nodes,function(el){io.observe(el);});if('MutationObserver' in window){new MutationObserver(function(records){for(var i=0;i<records.length;i++){var added=records[i].addedNodes;for(var j=0;j<added.length;j++){var node=added[j];if(1!==node.nodeType){continue;}if(node.matches && node.matches(SEL)){io.observe(node);}if(node.querySelectorAll){Array.prototype.forEach.call(node.querySelectorAll(SEL),function(child){io.observe(child);});}}}}).observe(document.documentElement,{childList:true,subtree:true});}}if('loading'===document.readyState){document.addEventListener('DOMContentLoaded',boot);}else{boot();}})();
